    "如果发生任何严重或意外反应，请立即停止使用。",
    "如果泡罩包装被刺破、撕裂或被篡改，请勿使用。",
    "如果不确定可能的药物相互作用，请咨询医疗保健专业人员。",
    "如果发生严重头晕、昏厥或突然虚弱，请寻求紧急关注。"
