    "负责任地处理空的泡罩包装。",
    "除非您的医生另有指示，否则保持正常水分。",
    "如果您感到不适、虚弱或发烧，请避免使用该产品。",
    "如果有任何使用说明不清楚，请询问您的医生。",
    "请勿将此药物与类似活性成分产品一起服用。",
