    "保持水分和一般健康以增强自然勃起功能。",
    "立即向医疗保健专业人员报告任何严重或长期的副作用。",
    "仅在需要时使用胶囊，不要作为日常补充剂。",
    "放在儿童接触不到的地方。",
    "服用胶囊前避免过量饮酒，因为这可能会降低疗效。",
